hooks.command:
python3 -c '
import sys, json, re, subprocess
try:
    raw = sys.stdin.read()
    data = json.loads(raw) if raw.strip() else {}
except Exception:
    data = {}
cmd = ""
if isinstance(data, dict):
    tc = data.get("toolCall") or {}
    args = tc.get("args") if isinstance(tc, dict) else {}
    if isinstance(args, dict):
        cmd = args.get("CommandLine", "")
    if not cmd and isinstance(data.get("args"), dict):
        cmd = data["args"].get("CommandLine", "")
if "agy-test-runner.sh" in cmd or "agy-test-runner.sh" in raw:
    err = data.get("error") if isinstance(data, dict) else None
    raw_lower = raw.lower()
    failed = bool(err) or bool(re.search(r"exit(ed with)? (code|status) [1-9]", raw_lower)) or bool(re.search(r"\"exit_code\"\s*:\s*[1-9]", raw))
    if not failed:
        root = subprocess.run(["git", "rev-parse", "--show-toplevel"], capture_output=True, text=True).stdout.strip() or "."
        subprocess.run(["git", "add", "-A"], cwd=root, check=False)
        if subprocess.run(["git", "diff", "--cached", "--quiet"], cwd=root).returncode != 0:
            subprocess.run(["git", "commit", "-m", "chore: auto-commit after green test gate"], cwd=root, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
print("{}")
'
